create or replace function public.vc_update_conversation(target uuid,source_number uuid,conversation_jid text,next_status text,assignee uuid) returns public.vc_conversations language plpgsql security definer set search_path='' as $$ declare r public.vc_conversations;begin
if public.vc_role(target)is null or next_status not in('open','pending','resolved') or conversation_jid !~ '^([1-9][0-9]{7,24}@(s\.whatsapp\.net|lid)|[0-9-]{8,40}@g\.us)$' or not exists(select 1 from public.vc_numbers where id=source_number and workspace_id=target)then raise exception 'Invalid conversation';end if;
if assignee is not null and not exists(select 1 from public.vc_memberships where workspace_id=target and user_id=assignee)then raise exception 'Invalid assignee';end if;
insert into public.vc_conversations(workspace_id,number_id,remote_jid,status,assigned_to)values(target,source_number,conversation_jid,next_status,assignee)on conflict(number_id,remote_jid)do update set status=excluded.status,assigned_to=excluded.assigned_to,updated_at=now() returning * into r;return r;end $$;
create or replace function public.vc_add_conversation_note(target uuid,source_number uuid,conversation_jid text,note_body text)returns public.vc_conversation_notes language plpgsql security definer set search_path='' as $$ declare c uuid;r public.vc_conversation_notes;begin
if public.vc_role(target)is null or char_length(trim(note_body))not between 1 and 2000 or conversation_jid !~ '^([1-9][0-9]{7,24}@(s\.whatsapp\.net|lid)|[0-9-]{8,40}@g\.us)$' or not exists(select 1 from public.vc_numbers where id=source_number and workspace_id=target)then raise exception 'Invalid note';end if;
insert into public.vc_conversations(workspace_id,number_id,remote_jid)values(target,source_number,conversation_jid)on conflict(number_id,remote_jid)do nothing;select id into c from public.vc_conversations where workspace_id=target and number_id=source_number and remote_jid=conversation_jid;insert into public.vc_conversation_notes(conversation_id,workspace_id,author_id,body)values(c,target,auth.uid(),trim(note_body))returning * into r;return r;end $$;
